import React, { useState, useEffect } from 'react';
import { makeStyles } from '@mui/styles';
import SEO from '../components/SEO';
import Breadcrumb from '../components/Breadcrumb';
import Sidebar from '../components/Sidebar';
import ShareButtons from '../components/ShareButtons';
import YouTubeLink from '../components/YouTubeLink';
import Footer from '../components/Footer';
import Flag from '../components/Flag';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Chip from '@mui/material/Chip';
import CircularProgress from '@mui/material/CircularProgress';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Grid';
import Avatar from '@mui/material/Avatar';
import Autocomplete from '@mui/material/Autocomplete';
import TextField from '@mui/material/TextField';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import LinearProgress from '@mui/material/LinearProgress';
import EventIcon from '@mui/icons-material/Event';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import CompareArrowsIcon from '@mui/icons-material/CompareArrows';
import { allCountries } from '../utils/generals';
import * as ARBApi from '../utils/ARBApi';

const useStyles = makeStyles((theme) => ({
  navCard: {
    borderTop: '4px solid #CA2331',
    marginBottom: theme.spacing(2),
    overflow: 'hidden',
  },
  navHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1.5),
    padding: theme.spacing(1, 2),
    backgroundImage: 'url(https://www.archiviorossoblu.it/images/header-gradient-bg.jpg)',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    position: 'relative',
    '&::before': {
      content: '""',
      position: 'absolute',
      inset: 0,
      background: 'rgba(8,45,104,0.60)',
    },
    '& > *': {
      position: 'relative',
      zIndex: 1,
    },
  },
  brand: {
    fontWeight: 800,
    fontSize: '1.6rem',
    color: '#F0C040',
    textDecoration: 'none',
    flex: 1,
  },
  content: {
    padding: theme.spacing(2),
  },
  playerCard: {
    borderTop: '4px solid #082D68',
    height: '100%',
  },
  sectionLabel: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: '#082D68',
    padding: theme.spacing(1.5, 0, 0.5),
  },
  statRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: theme.spacing(0.75, 0),
    borderBottom: '1px solid rgba(0,0,0,0.06)',
    '&:last-child': { borderBottom: 'none' },
  },
  statLabel: {
    fontSize: '0.8rem',
    color: 'rgba(0,0,0,0.6)',
    display: 'flex',
    alignItems: 'center',
    gap: 4,
  },
  statValue: {
    fontWeight: 700,
    fontSize: '1.1rem',
    color: '#082D68',
  },
  header: {
    fontSize: '0.72rem',
    fontWeight: 700,
    color: '#082D68',
    padding: '4px 8px',
  },
  cell: {
    padding: '4px 8px',
    fontSize: '0.78rem',
  },
  barWrap: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.75, 0),
    borderBottom: '1px solid rgba(0,0,0,0.06)',
    '&:last-child': { borderBottom: 'none' },
  },
}));

const getFlag = (countryName) => {
  if (!countryName) return null;
  return allCountries.find(c => c.description === countryName)?.flag;
};

const isGoalkeeper = (report) =>
  report?.data?.role?.toLowerCase().includes('portiere');

const computeTotals = (seasons = []) =>
  seasons.reduce((acc, s) => ({
    appareances: acc.appareances + (parseInt(s.appareances) > 0 ? parseInt(s.appareances) : 0),
    goal:        acc.goal        + (parseInt(s.goal) > 0 ? parseInt(s.goal) : 0),
  }), { appareances: 0, goal: 0 });

function StatBar({ label, icon, valA, valB, colorA = '#082D68', colorB = '#CA2331' }) {
  const classes = useStyles();
  const max = Math.max(valA, valB, 1);
  return (
    <div className={classes.barWrap}>
      <Typography style={{ fontSize: '0.75rem', fontWeight: 700, color: colorA, minWidth: 32, textAlign: 'right' }}>{valA}</Typography>
      <Box style={{ flex: 1 }}>
        <Box style={{ display: 'flex', alignItems: 'center', gap: 4, marginBottom: 2 }}>
          {icon}
          <Typography style={{ fontSize: '0.72rem', color: 'rgba(0,0,0,0.55)' }}>{label}</Typography>
        </Box>
        <Box style={{ display: 'flex', gap: 2, height: 8 }}>
          <Box style={{ flex: 1, display: 'flex', justifyContent: 'flex-end' }}>
            <LinearProgress
              variant="determinate"
              value={(valA / max) * 100}
              style={{ width: '100%', height: 8, borderRadius: 4, transform: 'scaleX(-1)' }}
              sx={{ '& .MuiLinearProgress-bar': { backgroundColor: colorA }, backgroundColor: 'rgba(8,45,104,0.08)' }}
            />
          </Box>
          <Box style={{ flex: 1 }}>
            <LinearProgress
              variant="determinate"
              value={(valB / max) * 100}
              style={{ width: '100%', height: 8, borderRadius: 4 }}
              sx={{ '& .MuiLinearProgress-bar': { backgroundColor: colorB }, backgroundColor: 'rgba(202,35,49,0.08)' }}
            />
          </Box>
        </Box>
      </Box>
      <Typography style={{ fontSize: '0.75rem', fontWeight: 700, color: colorB, minWidth: 32 }}>{valB}</Typography>
    </div>
  );
}

function PlayerPicker({ label, allPlayers, value, onChange, color }) {
  return (
    <Autocomplete
      options={allPlayers}
      getOptionLabel={p => p?.name || ''}
      value={value}
      onChange={(_, v) => onChange(v)}
      isOptionEqualToValue={(o, v) => o.id === v.id}
      renderInput={(params) => (
        <TextField
          {...params}
          label={label}
          size="small"
          InputProps={{
            ...params.InputProps,
            style: { fontSize: '0.85rem' },
          }}
          sx={{ '& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: color } }}
        />
      )}
      renderOption={(props, option) => (
        <li {...props} key={option.id}>
          <Box style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <Flag filename={getFlag(option.country)} country={option.country} />
            <Typography style={{ fontSize: '0.82rem' }}>{option.name}</Typography>
          </Box>
        </li>
      )}
    />
  );
}

function PlayerHeader({ report, color }) {
  if (!report) return null;
  const { data } = report;
  return (
    <Box style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px' }}>
      <Avatar
        src={data.photo ? `https://www.archiviorossoblu.it/images/giocatori/${data.photo}` : undefined}
        alt={[data.name, data.surname].filter(Boolean).join(' ')}
        style={{ width: 56, height: 56, border: `3px solid ${color}`, flexShrink: 0 }}
      />
      <Box>
        <Box style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
          <Flag filename={getFlag(data.country)} country={data.country} />
          <Typography style={{ fontWeight: 700, fontSize: '1rem', color }}>
            {[data.name, data.surname].filter(Boolean).join(' ')}
          </Typography>
        </Box>
        <Box style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
          {data.role && (
            <Chip label={data.role} size="small"
              style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
          )}
        </Box>
        {data.date && data.date !== '0000-00-00' && (
          <Typography style={{ fontSize: '0.72rem', color: 'rgba(0,0,0,0.5)', marginTop: 3 }}>
            {new Date(data.date).toLocaleDateString('it-IT', { day: '2-digit', month: 'long', year: 'numeric' })}
            {data.birthplace ? ` · ${data.birthplace}` : ''}
          </Typography>
        )}
      </Box>
    </Box>
  );
}

export default function ComparePage() {
  const classes = useStyles();
  const [allPlayers, setAllPlayers] = useState([]);
  const [playerA, setPlayerA] = useState(null);
  const [playerB, setPlayerB] = useState(null);
  const [reportA, setReportA] = useState(null);
  const [reportB, setReportB] = useState(null);
  const [loadingA, setLoadingA] = useState(false);
  const [loadingB, setLoadingB] = useState(false);

  useEffect(() => {
    fetch('/allPlayers.json').then(r => r.json()).then(setAllPlayers);
  }, []);

  useEffect(() => {
    if (!playerA) { setReportA(null); return; }
    setLoadingA(true);
    ARBApi.getAllByID('playerDetails', playerA.id).then(r => {
      setReportA(r?.data ? r : null);
      setLoadingA(false);
    });
  }, [playerA]);

  useEffect(() => {
    if (!playerB) { setReportB(null); return; }
    setLoadingB(true);
    ARBApi.getAllByID('playerDetails', playerB.id).then(r => {
      setReportB(r?.data ? r : null);
      setLoadingB(false);
    });
  }, [playerB]);

  const totA = reportA ? computeTotals(reportA.seasons) : null;
  const totB = reportB ? computeTotals(reportB.seasons) : null;

  const isGkA = playerA?.role?.toLowerCase().includes('portiere');
  const isGkB = playerB?.role?.toLowerCase().includes('portiere');
  const goalkeepers = allPlayers.filter(p => p.role?.toLowerCase().includes('portiere'));
  const optionsA = isGkB ? goalkeepers : allPlayers;
  const optionsB = isGkA ? goalkeepers : allPlayers;

  // Stagioni in comune
  const commonYears = reportA && reportB
    ? [...new Set([
        ...(reportA.seasons || []).map(s => s.year),
        ...(reportB.seasons || []).map(s => s.year),
      ])].sort((a, b) => String(b).localeCompare(String(a)))
    : [];

  return (
    <Box>
      <SEO
        title="Confronto giocatori"
        description="Confronta le statistiche di due giocatori del Cagliari Calcio: presenze, gol, ammonizioni, espulsioni e andamento stagionale."
        path="/cagliari-calcio/confronto"
      />

      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png" alt="logo" title="ArchivioRossoBlu"
              style={{ width: 80, height: 80, flexShrink: 0 }} />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label="Confronto" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
      </Card>

      <Box className={classes.content}>
        <Breadcrumb items={[{ label: 'Home', href: '/cagliari-calcio' }, { label: 'Confronto' }]} />
        {/* Selezione giocatori */}
        <Card style={{ borderTop: '4px solid #CA2331', marginBottom: 16 }}>
          <Box style={{ padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 8 }}>
            <CompareArrowsIcon style={{ color: '#082D68', fontSize: '1.2rem' }} />
            <Typography style={{ fontWeight: 700, fontSize: '0.9rem', color: '#082D68' }}>
              Seleziona due giocatori da confrontare
            </Typography>
          </Box>
          <Divider />
          <Box style={{ padding: '12px 16px', display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            <Box style={{ flex: 1, minWidth: 200 }}>
              <PlayerPicker
                label={isGkB ? 'Portiere A' : 'Giocatore A'}
                allPlayers={optionsA}
                value={playerA}
                onChange={(v) => { setPlayerA(v); if (v && !v.role?.toLowerCase().includes('portiere') && isGkB) setPlayerB(null); }}
                color="#082D68"
              />
            </Box>
            <Box style={{ display: 'flex', alignItems: 'center' }}>
              <Typography style={{ fontWeight: 800, color: 'rgba(0,0,0,0.3)', fontSize: '1.1rem' }}>VS</Typography>
            </Box>
            <Box style={{ flex: 1, minWidth: 200 }}>
              <PlayerPicker
                label={isGkA ? 'Portiere B' : 'Giocatore B'}
                allPlayers={optionsB}
                value={playerB}
                onChange={(v) => { setPlayerB(v); if (v && !v.role?.toLowerCase().includes('portiere') && isGkA) setPlayerA(null); }}
                color="#CA2331"
              />
            </Box>
          </Box>
        </Card>

        {/* Confronto */}
        {(playerA || playerB) && (
          <Grid container spacing={2}>
            {/* Intestazioni giocatori */}
            <Grid item xs={6}>
              <Card style={{ borderTop: '4px solid #082D68' }}>
                {loadingA
                  ? <Box style={{ padding: 24, display: 'flex', justifyContent: 'center' }}><CircularProgress size={24} style={{ color: '#082D68' }} /></Box>
                  : <PlayerHeader report={reportA} color="#082D68" />
                }
              </Card>
            </Grid>
            <Grid item xs={6}>
              <Card style={{ borderTop: '4px solid #CA2331' }}>
                {loadingB
                  ? <Box style={{ padding: 24, display: 'flex', justifyContent: 'center' }}><CircularProgress size={24} style={{ color: '#CA2331' }} /></Box>
                  : <PlayerHeader report={reportB} color="#CA2331" />
                }
              </Card>
            </Grid>

            {/* Barre di confronto */}
            {totA && totB && (
              <Grid item xs={12}>
                <Card>
                  <Box style={{ padding: '8px 16px 4px' }}>
                    <Typography className={classes.sectionLabel} style={{ paddingTop: 0 }}>Confronto carriera</Typography>
                  </Box>
                  <Divider />
                  <CardContent>
                    <StatBar
                      label="Presenze"
                      icon={<EventIcon style={{ fontSize: 13, color: 'rgba(0,0,0,0.4)' }} />}
                      valA={totA.appareances} valB={totB.appareances}
                    />
                    <StatBar
                      label={isGoalkeeper(reportA) || isGoalkeeper(reportB) ? 'Gol subiti' : 'Gol'}
                      icon={<SportsSoccerIcon style={{ fontSize: 13, color: 'rgba(0,0,0,0.4)' }} />}
                      valA={totA.goal} valB={totB.goal}
                    />
                    <StatBar
                      label="Stagioni"
                      icon={null}
                      valA={reportA.seasons?.length || 0} valB={reportB.seasons?.length || 0}
                    />
                  </CardContent>
                </Card>
              </Grid>
            )}

            {/* Tabella per stagione */}
            {commonYears.length > 0 && (
              <Grid item xs={12}>
                <Card>
                  <Box style={{ padding: '8px 16px 4px' }}>
                    <Typography className={classes.sectionLabel} style={{ paddingTop: 0 }}>Dettaglio stagioni</Typography>
                  </Box>
                  <Divider />
                  <TableContainer component={Paper} elevation={0}>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell className={classes.header} align="center" colSpan={2}
                            style={{ color: '#082D68', borderRight: '2px solid rgba(8,45,104,0.15)' }}>
                            {reportA ? [reportA.data?.name, reportA.data?.surname].filter(Boolean).join(' ') : '—'}
                          </TableCell>
                          <TableCell className={classes.header} align="center" style={{ backgroundColor: 'rgba(0,0,0,0.02)' }}>
                            Stagione
                          </TableCell>
                          <TableCell className={classes.header} align="center" colSpan={2}
                            style={{ color: '#CA2331', borderLeft: '2px solid rgba(202,35,49,0.15)' }}>
                            {reportB ? [reportB.data?.name, reportB.data?.surname].filter(Boolean).join(' ') : '—'}
                          </TableCell>
                        </TableRow>
                        <TableRow>
                          {(() => {
                            const goalLabel = isGoalkeeper(reportA) || isGoalkeeper(reportB) ? 'Gol sub.' : 'Gol';
                            return (<>
                              <TableCell className={classes.header} align="center" style={{ color: '#082D68' }}>Pres.</TableCell>
                              <TableCell className={classes.header} align="center" style={{ color: '#082D68', borderRight: '2px solid rgba(8,45,104,0.15)' }}>{goalLabel}</TableCell>
                              <TableCell className={classes.header} align="center" style={{ backgroundColor: 'rgba(0,0,0,0.02)', fontWeight: 800 }}>Anno</TableCell>
                              <TableCell className={classes.header} align="center" style={{ color: '#CA2331', borderLeft: '2px solid rgba(202,35,49,0.15)' }}>Pres.</TableCell>
                              <TableCell className={classes.header} align="center" style={{ color: '#CA2331' }}>{goalLabel}</TableCell>
                            </>);
                          })()}
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {commonYears.map(year => {
                          const sA = reportA?.seasons?.find(s => s.year === year);
                          const sB = reportB?.seasons?.find(s => s.year === year);
                          const cell = (val) => val !== undefined && parseInt(val) !== -1 ? parseInt(val) || 0 : '—';
                          return (
                            <TableRow key={year} style={{ backgroundColor: sA && sB ? 'rgba(8,45,104,0.02)' : undefined }}>
                              <TableCell className={classes.cell} align="center" style={{ color: '#082D68', fontWeight: sA ? 600 : 400 }}>{sA ? cell(sA.appareances) : '—'}</TableCell>
                              <TableCell className={classes.cell} align="center" style={{ color: '#082D68', borderRight: '2px solid rgba(8,45,104,0.15)' }}>{sA ? cell(sA.goal) : '—'}</TableCell>
                              <TableCell className={classes.cell} align="center" style={{ backgroundColor: 'rgba(0,0,0,0.02)', fontWeight: 700 }}>{year}</TableCell>
                              <TableCell className={classes.cell} align="center" style={{ color: '#CA2331', fontWeight: sB ? 600 : 400, borderLeft: '2px solid rgba(202,35,49,0.15)' }}>{sB ? cell(sB.appareances) : '—'}</TableCell>
                              <TableCell className={classes.cell} align="center" style={{ color: '#CA2331' }}>{sB ? cell(sB.goal) : '—'}</TableCell>
                            </TableRow>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </Card>
              </Grid>
            )}
          </Grid>
        )}

        {!playerA && !playerB && (
          <Box style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, padding: '40px 0', color: 'rgba(0,0,0,0.3)' }}>
            <CompareArrowsIcon style={{ fontSize: 48 }} />
            <Typography style={{ fontSize: '0.9rem' }}>Seleziona due giocatori per avviare il confronto</Typography>
          </Box>
        )}
      </Box>

      <Footer />
    </Box>
  );
}
